 */
scwin.dts_List2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05323.dts_List2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List2_OnLoadCompleted
 * @description dts_List2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05323.dts_List2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_synthEtfIsuSearch_onclick
 * @description img_synthEtfIsuSearch 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_synthEtfIsuSearch_onclick = async function() {
    try {
        await scwin.popFindSynthEftIsu();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05323.img_synthEtfIsuSearch_onclick" });
    }
};

/**
 * @method
 * @name img_Date_onclick
 * @description img_Date 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Date_onclick = function() {
    try {
        popUpCalendar2(edt_Date);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05323.img_Date_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05323.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05323.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        if ($c.frame.path("NoData") !== null) {
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05323.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name btn_excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_excel_onclick = function() {
    try {
        const vsTabSel = MaxTab_01.getSelectedTabIndex();
        $c.stf.doLogSave("ULDSTF05323.xml", SCREN_PROCS_TP_CD_07);
        if (vsTabSel === "1") {
            $c.data.downloadGridViewExcel(grd_List1, {fileName: "합성 ETF 신용등급현황", type: "8"});
        } else if (vsTabSel === "2") {
            $c.data.downloadGridViewExcel(grd_List2, {fileName: "합성 ETF 순자본비율", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05323.btn_excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        await scwin.input();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05323.btn_Input_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    /*
    	신용등급현황조회
     */
    url += "&inputMessageId=LISTCREDITGRADE_INOUT&outputMessageId=LISTCREDITGRADE_INOUT";
    url += "&ISU_CD=" + txb_ISU_CD.getValue();
    url += "&DISCLS_DD=" + edt_Date.getValue();
    const sbmOptions = {
        id : "sbm_dts_List1",
        action : "/SynthEtfTrctptInfo.do",
        ref : "",
        target : "dts_List1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /*
    	영업용순자본비율 조회
     */

    url += "&inputMessageId=LISTNETCAPITALRATIO_INOUT&outputMessageId=LISTNETCAPITALRATIO_INOUT";
    url += "&ISU_CD=" + txb_ISU_CD.getValue();
    url += "&DISCLS_DD=" + edt_Date.getValue();
    const sbmOptions2 = {
        id : "sbm_dts_List2",
        action : "/SynthEtfTrctptInfo.do",
        ref : "",
        target : "dts_List2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getPar
 * @description 오늘날짜
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISU_CD.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_ISU_NM.getValue(); // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_ENG_NM);
};

/**
 * @method
 * @name popFindSynthEftIsu
 * @description 합성ETF 팝업호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popFindSynthEftIsu = async function() {
    const options = {
        id: "ULDSTF05016",
        title: "합성EFT종목선택",
        type: "browserPopup",
        width: "420px",
        height: "720px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("../lstproc/ULDSTF05016.gfm", options);
};

/**
 * @method
 * @name input
 * @description 일괄등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input = async function() {
    const options = {
        id: "ULDSTF05328",
        title: "합성ETF 신용등급/순자본비율 입력",
        type: "browserPopup",
        width: "780px",
        height: "445px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstproc/ULDSTF05328.gfm", options);
};
